def _clean_year_keys(raw: dict[int, dict] | dict[str, dict]) -> dict[str, dict]:
    cleaned: dict[str, dict] = {}
    for number, payload in raw.items():
        if not (payload.get("Correct Option") or payload.get("deleted")):
            continue
        entry = {
            "Correct Option": payload.get("Correct Option"),
            "Correct percentage": payload.get("Correct percentage"),
        }
        if payload.get("deleted"):
            entry["deleted"] = True
        cleaned[str(number)] = entry
    return cleaned


def keys_from_manual() -> dict[str, dict[str, dict]]:
    return {year: _clean_year_keys(payload) for year, payload in MANUAL_KEYS.items()}


def load_answer_keys(
    answers_dir: Path,
    keys_path: Path,
    *,
    refresh: bool,
) -> dict[str, dict[str, dict]]:
    if keys_path.is_file() and not refresh:
        keys = json.loads(keys_path.read_text(encoding="utf-8"))
        print(f"  loaded cache {keys_path} ({sum(len(v) for v in keys.values())} keys)", flush=True)
